    out[6] = hu[0]*hp[0]*(dyn_par[18]*dyn_par[7] - dyn_par[19]*dyn_par[6]) + hu[1]*hp[0]*(dyn_par[21]*dyn_par[10] - dyn_par[22]*dyn_par[9]) + hu[2]*hp[0]*(dyn_par[24]*dyn_par[13] - dyn_par[25]*dyn_par[12]) + hu[3]*hp[0]*(dyn_par[27]*dyn_par[16] - dyn_par[28]*dyn_par[15]) - hx[4]*hp[0]*(2*hx[4]*(dyn_par[3]*dyn_par[2] - dyn_par[4]*dyn_par[5]) - hx[5]*(dyn_par[0]*dyn_par[2] - pow(dyn_par[4], 2)) + hx[5]*(dyn_par[1]*dyn_par[2] - pow(dyn_par[5], 2)) + hx[6]*(dyn_par[0]*dyn_par[5] - dyn_par[3]*dyn_par[4]))/(-dyn_par[0]*dyn_par[1]*dyn_par[2] + dyn_par[0]*pow(dyn_par[5], 2) + pow(dyn_par[3], 2)*dyn_par[2] - 2*dyn_par[3]*dyn_par[4]*dyn_par[5] + pow(dyn_par[4], 2)*dyn_par[1]) - hx[5]*hp[0]*(hx[4]*(-dyn_par[0]*dyn_par[2] + pow(dyn_par[4], 2)) + hx[4]*(dyn_par[1]*dyn_par[2] - pow(dyn_par[5], 2)) + hx[5]*(-dyn_par[3]*dyn_par[2] + dyn_par[4]*dyn_par[5]) - hx[5]*(dyn_par[3]*dyn_par[2] - dyn_par[4]*dyn_par[5]) + hx[6]*(dyn_par[3]*dyn_par[5] - dyn_par[4]*dyn_par[1]))/(-dyn_par[0]*dyn_par[1]*dyn_par[2] + dyn_par[0]*pow(dyn_par[5], 2) + pow(dyn_par[3], 2)*dyn_par[2] - 2*dyn_par[3]*dyn_par[4]*dyn_par[5] + pow(dyn_par[4], 2)*dyn_par[1]) - hx[6]*hp[0]*(hx[4]*(dyn_par[0]*dyn_par[5] - dyn_par[3]*dyn_par[4]) + hx[5]*(dyn_par[3]*dyn_par[5] - dyn_par[4]*dyn_par[1]))/(-dyn_par[0]*dyn_par[1]*dyn_par[2] + dyn_par[0]*pow(dyn_par[5], 2) + pow(dyn_par[3], 2)*dyn_par[2] - 2*dyn_par[3]*dyn_par[4]*dyn_par[5] + pow(dyn_par[4], 2)*dyn_par[1]);
